def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find full-width and full-height separator lines.
    row_seps = [r for r in range(h) if len(set(grid[r])) == 1]
    col_seps = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def segments(n, seps):
        bounds = [-1] + seps + [n]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)
                if bounds[i] + 1 < bounds[i + 1]]

    rows = segments(h, row_seps)
    cols = segments(w, col_seps)

    background = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    best = None
    best_count = -1
    for r0, r1 in rows:
        for c0, c1 in cols:
            count = sum(grid[r][c] != background
                        for r in range(r0, r1) for c in range(c0, c1))
            if count > best_count:
                best_count, best = count, (r0, r1, c0, c1)

    r0, r1, c0, c1 = best
    tile = [grid[r][c0:c1] for r in range(r0, r1)]
    out = [row[:] for row in grid]
    for a, b in rows:
        for x, y in cols:
            for i in range(b - a):
                for j in range(y - x):
                    out[a + i][x + j] = tile[i][j]
    return out
